// Regenerates src/features/audience/protocols.generated.ts — the local registry
// of top DeFi protocols (name + DefiLlama slug) that backs the audience Apps
// column. Sources DefiLlama's protocols list, keeps the top ~110 by TVL
// (excluding CEX/Chain/Bridge/Infra), and keys each by its normalized slug and
// brand token so a backend protocol slug (e.g. aave_v3 → aave) resolves to a
// clean display name and the DefiLlama icon.
//
//   node scripts/generate-protocol-registry.mjs
//
// Run it periodically to pick up new protocols. Commit the regenerated file, then
// `npx eslint --fix` it (this writes JSON-quoted keys; eslint reformats to the
// repo's Prettier style).

import { writeFileSync } from "node:fs";

const LIMIT = 110;
const EXCLUDE = new Set([
  "CEX",
  "Chain",
  "Bridge",
  "Infrastructure",
  "Staking Pool",
]);
const OUT = new URL(
  "../src/features/audience/protocols.generated.ts",
  import.meta.url
);

const norm = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
// Trim trailing product-type/version words so "Aave V3" → "Aave", "Curve DEX" →
// "Curve", leaving a clean brand name for the chip.
const cleanName = (n) =>
  n.replace(/\s+(v\d+(\.\d+)?|amm|clmm|dex|perps?|lend(ing)?|blue|ssv)$/i, "").trim() ||
  n;

const res = await fetch("https://api.llama.fi/protocols");
if (!res.ok) throw new Error(`DefiLlama ${res.status}`);
const all = await res.json();

const seen = new Set();
const picked = [];
for (const p of [...all].sort((a, b) => (b.tvl || 0) - (a.tvl || 0))) {
  if (!p.slug || !p.name || EXCLUDE.has(p.category) || seen.has(p.slug)) continue;
  seen.add(p.slug);
  picked.push({ name: cleanName(p.name), slug: p.slug });
  if (picked.length >= LIMIT) break;
}

const registry = {};
const add = (key, entry) => {
  if (key && !registry[key]) registry[key] = entry;
};
for (const p of picked) {
  const entry = { name: p.name, slug: p.slug };
  add(norm(p.slug), entry);
  add(norm(p.slug.split("-")[0]), entry); // brand token
  add(norm(p.name.split(/\s+/)[0]), entry);
}

const header =
  `// GENERATED by scripts/generate-protocol-registry.mjs — do not edit by hand.\n` +
  `// Top DeFi protocols from DefiLlama (api.llama.fi/protocols) by TVL, excluding\n` +
  `// CEX/Chain/Bridge/Infra. ${picked.length} protocols, ${Object.keys(registry).length} lookup keys.\n\n` +
  `export interface ProtocolRegistryEntry {\n` +
  `  /** Clean brand name, e.g. "Aave". */\n  name: string;\n` +
  `  /** DefiLlama slug for the icon CDN. */\n  slug: string;\n}\n\n` +
  `export const PROTOCOL_REGISTRY: Record<string, ProtocolRegistryEntry> = ${JSON.stringify(
    registry,
    null,
    2
  )};\n`;

writeFileSync(OUT, header);
console.log(
  `Wrote ${picked.length} protocols / ${Object.keys(registry).length} keys to ${OUT.pathname}`
);
console.log("Now run: npx eslint --fix src/features/audience/protocols.generated.ts");
